PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?member_member ?memberName ?holding_holding ?holdingStart ?holdingEnd WHERE {
  GRAPH ?memberGraph {

    ?member_member a agents:Member ; foaf:name ?memberName ;
      members:hasOfficeHolding ?holding_holding .
    ?holding_holding a members:OfficeHolding ;
      members:heldOffice <https://data.oireachtas.ie/office/o-000001> ;
      members:hasMembershipDateRange ?holdingDateRange .
    ?holdingDateRange a members:DateRange ; members:StartDate ?holdingStart .
    OPTIONAL { ?holdingDateRange members:EndDate ?holdingEnd . }
  }
  FILTER(STRSTARTS(STR(?memberGraph), "https://data.oireachtas.ie/graph/member/"))
  GRAPH <https://data.oireachtas.ie/graph/offices> { <https://data.oireachtas.ie/office/o-000001> a members:NamedOffice ; skos:prefLabel ?officeLabel . }
  FILTER(DATATYPE(?holdingStart) = xsd:dateTime)
  FILTER(?holdingStart < "1994-07-01T00:00:00"^^xsd:dateTime)
  FILTER(!BOUND(?holdingEnd) || (DATATYPE(?holdingEnd) = xsd:dateTime && ?holdingEnd >= "1994-06-01T00:00:00"^^xsd:dateTime))
} ORDER BY ?holdingStart ?memberName ?holding_holding
LIMIT 100

