GRAPH ?anchorGraph { ?anchor a agents:Member . VALUES ?anchor { <https://data.oireachtas.ie/ie/oireachtas/member/id/Bertie-Ahern.D.1977-07-05> } ?anchor_membership a members:DailMembership . ?holding a members:OfficeHolding . ?anchor members:hasMembersMembership ?anchor_membership . ?anchor_membership members:inHouseTerm ?term . ?anchor_membership members:isRepresentativeFrom ?constituency . ?anchor members:hasOfficeHolding ?holding . ?holding members:heldOffice ?office . OPTIONAL { ?anchor_membership members:hasMembershipDateRange ?anchorMembershipRange .
