SELECT DISTINCT ?member ?memberName ?membership ?membershipRange ?membershipStart ?membershipEnd WHERE {
  GRAPH ?memberGraph {
    ?member a agents:Member .
    OPTIONAL { ?member foaf:name ?memberName . }
    ?membership a members:DailMembership .
    ?member members:hasMembersMembership ?membership .
    ?membership members:inHouseTerm ?term .
    ?membership members:isRepresentativeFrom ?constituency .
    OPTIONAL { ?membership members:hasMembershipDateRange ?membershipRange .
      ?membershipRange a members:DateRange .
      OPTIONAL { ?membershipRange members:StartDate ?membershipStart . }
      OPTIONAL { ?membershipRange members:EndDate ?membershipEnd . } }
  }
  FILTER(STRSTARTS(STR(?memberGraph), "https://data.oireachtas.ie/graph/member/"))
  GRAPH <https://data.oireachtas.ie/graph/houses> {
    ?term a agents:DailTerm .
    VALUES ?term { <https://data.oireachtas.ie/ie/oireachtas/house/dail/34> }
  }
  GRAPH <https://data.oireachtas.ie/graph/constituencies> {
    ?constituency a members:DailConstituency .
    VALUES ?constituency { <https://data.oireachtas.ie/ie/oireachtas/house/dail/34/constituency/Meath-East> }
    ?constituency members:constituencyInHouseTerm ?term .
  }
} ORDER BY ?memberName ?member ?membership LIMIT 100 OFFSET 0

