PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?member ?memberName WHERE {
  GRAPH ?memberGraph {
    ?member a agents:Member .
    OPTIONAL { ?member foaf:name ?memberName . }
    ?membership a members:DailMembership .
    ?member members:hasMembersMembership ?membership .
    ?membership members:inHouseTerm ?term .
    ?membership members:isRepresentativeFrom ?constituency .
  }
  FILTER(STRSTARTS(STR(?memberGraph), "https://data.oireachtas.ie/graph/member/"))
  GRAPH ?anchorGraph {
    ?anchorMember a agents:Member .
    VALUES ?anchorMember { <https://data.oireachtas.ie/ie/oireachtas/member/id/Mary-Lou-McDonald.D.2011-03-09> }
    ?anchorMembership a members:DailMembership .
    ?anchorMember members:hasMembersMembership ?anchorMembership .
    ?anchorMembership members:inHouseTerm ?term .
    ?anchorMembership members:isRepresentativeFrom ?constituency .
  }
  FILTER(STRSTARTS(STR(?anchorGraph), "https://data.oireachtas.ie/graph/member/"))
  GRAPH <https://data.oireachtas.ie/graph/houses> {
    ?term a agents:DailTerm .
    VALUES ?term { <https://data.oireachtas.ie/ie/oireachtas/house/dail/33> }
  }
  GRAPH <https://data.oireachtas.ie/graph/constituencies> {
    ?constituency a members:DailConstituency .
    VALUES ?constituency { <https://data.oireachtas.ie/ie/oireachtas/house/dail/33/constituency/Dublin-Central> }
    ?constituency members:constituencyInHouseTerm ?term .
  }
  FILTER(?member != ?anchorMember)
  FILTER(?anchorMembership != ?membership)
} ORDER BY ?memberName ?member LIMIT 100 OFFSET 0

